package com.qfk.match.service;
import com.qfk.match.entity.*; import com.qfk.match.repository.*; import com.qfk.member.entity.Member; import jakarta.persistence.EntityManager; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class RegistrationService {private final MatchRepository matches;private final RegistrationRepository registrations;private final EntityManager em; public RegistrationService(MatchRepository m,RegistrationRepository r,EntityManager e){matches=m;registrations=r;em=e;}
 @Transactional public MatchRegistration register(UUID matchId,Member member){var match=matches.findByIdForRegistration(matchId).orElseThrow();if(match.status!=FootballMatch.MatchStatus.REGISTRATION_OPEN&&match.status!=FootballMatch.MatchStatus.FULL)throw new IllegalStateException("Registration is not open");if(registrations.existsByMatchIdAndMemberId(matchId,member.id))throw new IllegalStateException("Member is already registered");long confirmed=registrations.countByMatchIdAndStatus(matchId,MatchRegistration.Status.CONFIRMED);var r=new MatchRegistration();r.match=match;r.member=member;r.registeredAt=Instant.now();r.status=confirmed<match.maximumPlayers?MatchRegistration.Status.CONFIRMED:MatchRegistration.Status.WAITLIST;if(r.status==MatchRegistration.Status.WAITLIST)r.waitlistPosition=(int)(registrations.countByMatchIdAndStatus(matchId,MatchRegistration.Status.WAITLIST)+1);if(confirmed+1>=match.maximumPlayers)match.status=FootballMatch.MatchStatus.FULL;return registrations.save(r);}
 @Transactional public void cancel(UUID id){var registration=registrations.findById(id).orElseThrow();boolean promote=registration.status==MatchRegistration.Status.CONFIRMED;registration.status=MatchRegistration.Status.CANCELLED;if(promote)registrations.findFirstByMatchIdAndStatusOrderByRegisteredAtAsc(registration.match.id,MatchRegistration.Status.WAITLIST).ifPresent(next->{next.status=MatchRegistration.Status.CONFIRMED;next.waitlistPosition=null;});registration.match.status=FootballMatch.MatchStatus.REGISTRATION_OPEN;}
}
